    def __init__(self, size):
        self.size = size
        self.q = []
        self.window_sum = 0
    def next(self, val):
        self.q.append(val)
        self.window_sum += val
        if len(self.q) > self.size:
            self.window_sum -= self.q.pop(0)
        return float(self.window_sum) / len(self.q)""",
