"import json
import glob
import requests
import os
import time

STATE_FILE = '.local/state.json'

if os.path.exists(STATE_FILE):
    with open(STATE_FILE, 'r') as f:
        state = json.load(f)
else:
    state = {}

for manifest_file in glob.glob('solutions_manifests/*.json'):
    basename = os.path.basename(manifest_file)
    # Handle assignment_1.json, assignment_2.json, etc.
    if 'assignment_' in basename:
        assignment_id = basename.split('_')[1].split('.')[0]
    else:
        assignment_id = basename.split('.')[0]

    print(f"Checking {manifest_file} (Assignment ID: {assignment_id})")

    with open(manifest_file, 'r', encoding='utf-8') as f:
        data = json.load(f)

    for prob in data:
        leetcode_id = str(prob.get('leetcode_id'))
        url = prob.get('url', '')
        if not url:
            continue

        slug = [p for p in url.split('/') if p][-1]

        curr_state = state.get(assignment_id, {}).get(leetcode_id, {}).get('state')
        if curr_state == 'SUBSCRIBER_ONLY':
            continue # Already checked

        query = {
            "operationName": "questionData",
            "variables": {"titleSlug": slug},
            "query": "query questionData($titleSlug: String!) { question(titleSlug: $titleSlug) { isPaidOnly } }"
        }

        try:
            resp = requests.post("https://leetcode.com/graphql/", json=query, headers={'User-Agent': 'Mozilla/5.0'})
            if resp.status_code == 200:
                result = resp.json()
                question_data = result.get('data', {}).get('question')
                if question_data:
                    is_paid = question_data.get('isPaidOnly', False)
                    if is_paid:
