os.makedirs(".local/screenshots", exist_ok=True)
os.makedirs(".local/reports", exist_ok=True)

# Move screenshots contents
if os.path.exists("screenshots"):
    for item in os.listdir("screenshots"):
        src = os.path.join("screenshots", item)
        dst = os.path.join(".local", "screenshots", item)
        if os.path.isdir(src):
            if os.path.exists(dst):
                for sub in os.listdir(src):
                    shutil.move(os.path.join(src, sub), os.path.join(dst, sub))
                shutil.rmtree(src)
            else:
                shutil.move(src, dst)
        else:
            if not os.path.exists(dst):
                shutil.move(src, dst)
    try:
        shutil.rmtree("screenshots")
    except: pass

# Move reports
for doc in glob.glob("25070126076_*.docx"):
    dst = os.path.join(".local", "reports", doc)
    if not os.path.exists(dst):
        shutil.move(doc, dst)

# Delete stray py files like patch_report_engine.py
for stray in glob.glob("patch_*.py"):
    try:
        os.remove(stray)
    except: pass
try:
    os.remove("sweep_premium.py")
except: pass
try:
    os.remove("test_gql.py")
except: pass
